:root {
  --fg: #1f2328;
  --muted: #6b7280;
  --bg: #f7f8fa;
  --card: #ffffff;
  --border: #e3e6ea;
  --accent: #2563eb;
  --danger: #dc2626;
  --radius: 10px;
  --font: 15px;
}
:root[data-text-size='small'] { --font: 13px; }
:root[data-text-size='large'] { --font: 17px; }

* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  color: var(--fg);
  background: var(--bg);
  font-size: var(--font);
}
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }

.app { max-width: 900px; margin: 0 auto; padding: 0 16px 64px; }
.topbar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 16px 0; position: sticky; top: 0; background: var(--bg); z-index: 5;
}
.topbar h1 { font-size: 1.3rem; margin: 0; }
.topbar nav { display: flex; gap: 14px; }
.topbar nav a { color: var(--muted); font-weight: 600; padding: 4px 2px; }
.topbar nav a.active { color: var(--fg); border-bottom: 2px solid var(--accent); }

button, .button {
  font: inherit; padding: 7px 12px; border: 1px solid var(--border);
  background: #fff; border-radius: 8px; cursor: pointer; color: var(--fg);
}
button:hover { background: #f0f2f5; }
button:disabled { opacity: 0.5; cursor: default; }
button.primary, .button.primary { background: var(--accent); color: #fff; border-color: var(--accent); }
button.primary:hover { background: #1d4fd7; }
button.danger { color: var(--danger); border-color: #f0c2c2; }
.linklike { border: none; background: none; color: var(--accent); padding: 2px 4px; }
.spacer { flex: 1; }

.list-head { display: flex; align-items: center; justify-content: space-between; }
.list-head h2 { margin: 8px 0 12px; }

.search-row { display: flex; gap: 8px; margin-bottom: 12px; flex-wrap: wrap; }
.search { flex: 1; min-width: 240px; padding: 9px 12px; border: 1px solid var(--border); border-radius: 8px; }
select { padding: 8px 10px; border: 1px solid var(--border); border-radius: 8px; background: #fff; }

.filters-bar, .bulk-bar, .all-matching { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-bottom: 12px; }
.bulk-bar { background: #eef2ff; padding: 8px 12px; border-radius: 8px; }
.label { color: var(--muted); font-size: 0.9em; }

.cards { display: flex; flex-direction: column; gap: 10px; }
.card {
  display: flex; gap: 12px; align-items: flex-start;
  background: var(--card); border: 1px solid var(--border); border-radius: var(--radius); padding: 12px 14px;
}
.card.selected { outline: 2px solid var(--accent); }
.card .select { margin-top: 4px; }
.favicon { border-radius: 4px; margin-top: 2px; flex: none; background: #fff; object-fit: contain; }
.card-body { flex: 1; min-width: 0; }
.card-head { display: flex; align-items: center; gap: 8px; }
.title { font-weight: 650; font-size: 1.05em; }
.host { color: var(--muted); font-size: 0.85em; margin: 1px 0 4px; }
.desc { margin: 4px 0; color: #384049; }
.badge { font-size: 0.7em; background: #fde68a; color: #92400e; padding: 1px 7px; border-radius: 999px; font-weight: 700; }
.tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; }
.card-actions { display: flex; flex-direction: column; gap: 6px; }
.card-actions button { font-size: 0.85em; padding: 4px 8px; }

.chip {
  display: inline-flex; align-items: center; gap: 4px; background: #eef2f7;
  border-radius: 999px; padding: 2px 6px 2px 10px; font-size: 0.85em; border: none;
}
.chip.small { padding: 2px 9px; color: var(--accent); background: #eef2ff; cursor: pointer; }
.chip button { border: none; background: none; padding: 0 2px; cursor: pointer; color: var(--muted); font-size: 1em; }
.chip.filter { padding-left: 4px; }
.chip.filter.selected { background: var(--accent); color: #fff; }
.chip.filter button { color: inherit; }

.empty { text-align: center; color: var(--muted); padding: 48px 16px; background: var(--card); border: 1px dashed var(--border); border-radius: var(--radius); }
.error { color: var(--danger); }
.muted { color: var(--muted); font-size: 0.9em; }

.pager { display: flex; align-items: center; justify-content: center; gap: 14px; margin-top: 18px; color: var(--muted); }

/* modal */
.modal-backdrop { position: fixed; inset: 0; background: rgba(0,0,0,0.35); display: flex; align-items: flex-start; justify-content: center; padding: 48px 16px; overflow: auto; z-index: 20; }
.modal { background: #fff; border-radius: 12px; padding: 20px 22px; width: 560px; max-width: 100%; box-shadow: 0 12px 40px rgba(0,0,0,0.2); }
.modal h2 { margin: 0 0 12px; }
.modal label { display: block; margin: 12px 0 4px; font-weight: 600; font-size: 0.9em; }
.modal input, .modal textarea { width: 100%; padding: 8px 10px; border: 1px solid var(--border); border-radius: 8px; font: inherit; }
.modal .row { display: flex; gap: 8px; }
.modal .row input { flex: 1; }
.modal-actions { display: flex; align-items: center; gap: 8px; margin-top: 18px; }
.checkbox { display: flex; align-items: center; gap: 8px; font-weight: 500 !important; }
.checkbox input { width: auto; }
.preview { max-width: 100%; max-height: 160px; object-fit: cover; border-radius: 8px; margin-top: 8px; }
.note-preview { border: 1px solid var(--border); border-radius: 8px; padding: 8px 12px; background: #fafbfc; }
.copy-links { display: flex; align-items: center; gap: 12px; margin-top: 14px; flex-wrap: wrap; font-size: 0.9em; }

/* tag input */
.tag-input { border: 1px solid var(--border); border-radius: 8px; padding: 6px; }
.tag-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 4px; }
.tag-entry { position: relative; }
.tag-entry input { width: 100%; border: none; padding: 6px; outline: none; }
.suggestions { position: absolute; top: 100%; left: 0; right: 0; background: #fff; border: 1px solid var(--border); border-radius: 8px; margin: 2px 0 0; padding: 4px; list-style: none; z-index: 30; box-shadow: 0 6px 20px rgba(0,0,0,0.12); }
.suggestions button { width: 100%; text-align: left; border: none; background: none; padding: 6px 8px; border-radius: 6px; }
.suggestions button:hover { background: #eef2ff; }

.settings section { background: var(--card); border: 1px solid var(--border); border-radius: var(--radius); padding: 16px 18px; margin-bottom: 16px; }
.settings h3 { margin-top: 0; }
.settings label { display: block; margin: 12px 0 4px; font-weight: 600; font-size: 0.9em; }
.settings .row { display: flex; gap: 10px; align-items: center; }

